import { DBSchema, IDBPDatabase, openDB } from 'idb';
import { AppData } from './appData';

export interface SyncInfo {
    fileId: string | null;
    modifiedTime: string | null;   // modifiedTime файла на Диску при останній синхронізації
    version: string | null;
    dirty: boolean;                // є локальні зміни, яких ще немає на Диску
}

export const EMPTY_SYNC: SyncInfo = { fileId: null, modifiedTime: null, version: null, dirty: false };

export interface LocalStore {
    load(userId: string): Promise<{ data: AppData; sync: SyncInfo } | null>;
    save(userId: string, data: AppData, sync: SyncInfo): Promise<void>;
    clear(userId: string): Promise<void>;
}

interface TutorDB extends DBSchema {
    kv: { key: string; value: unknown };
}

let dbPromise: Promise<IDBPDatabase<TutorDB>> | null = null;
const db = () => {
    if (!dbPromise) {
        dbPromise = openDB<TutorDB>('tutor-helper', 1, {
            upgrade(d) { d.createObjectStore('kv'); },
        });
    }
    return dbPromise;
};

export const localStore: LocalStore = {
    async load(userId) {
        const d = await db();
        const data = (await d.get('kv', `data:${userId}`)) as AppData | undefined;
        if (data === undefined) return null;
        const sync = ((await d.get('kv', `sync:${userId}`)) as SyncInfo | undefined) ?? { ...EMPTY_SYNC };
        return { data, sync };
    },
    async save(userId, data, sync) {
        const d = await db();
        const tx = d.transaction('kv', 'readwrite');
        await Promise.all([tx.store.put(data, `data:${userId}`), tx.store.put(sync, `sync:${userId}`), tx.done]);
    },
    async clear(userId) {
        const d = await db();
        const tx = d.transaction('kv', 'readwrite');
        await Promise.all([tx.store.delete(`data:${userId}`), tx.store.delete(`sync:${userId}`), tx.done]);
    },
};