export interface AppData {
    schemaVersion: number;
    [key: string]: unknown;
}

export const CURRENT_SCHEMA_VERSION = 1;

export const createEmptyData = (): AppData => ({ schemaVersion: CURRENT_SCHEMA_VERSION });

// У 3.5 це буде повна перевірка схемою zod
export function parseAppData(raw: unknown): AppData {
    if (typeof raw !== 'object' || raw === null || typeof (raw as AppData).schemaVersion !== 'number') {
        throw new Error('Файл data.json має невідомий формат');
    }
    return raw as AppData;
}
