import { createContext, ReactNode, useCallback, useContext, useMemo, useRef, useState } from 'react';
import { googleLogout, useGoogleLogin } from '@react-oauth/google';
import { AuthError } from './errors';


export const GOOGLE_SCOPE = 'openid email profile https://www.googleapis.com/auth/drive.appdata';
const REFRESH_MARGIN_MS = 60_000;   // оновлювати токен за хвилину до завершення
const SILENT_TIMEOUT_MS = 15_000;   // скільки чекати на оновлення токена


type Waiter = { resolve: (t: string) => void; reject: (e: Error) => void };

interface AuthContextValue {
    email: string | null;
    userId: string | null;
    isSignedIn: boolean;
    needsReauth: boolean;               // оновити токен тихо не вдалося, потрібен клік
    signIn: () => void;
    signOut: () => void;
    getToken: () => Promise<string>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
    const [email, setEmail] = useState<string | null>(null);
    const [isSignedIn, setIsSignedIn] = useState(false);
    const [needsReauth, setNeedsReauth] = useState(false);
    const token = useRef<{ value: string; expiresAt: number } | null>(null);
    const waiters = useRef<Waiter[]>([]);
    const [userId, setUserId] = useState<string | null>(null);

    const settle = (err: Error | null, value?: string) => {
        waiters.current.splice(0).forEach((w) => (err ? w.reject(err) : w.resolve(value!)));
    };

    const login = useGoogleLogin({
        scope: GOOGLE_SCOPE,
        onSuccess: async (resp) => {
            token.current = { value: resp.access_token, expiresAt: Date.now() + resp.expires_in * 1000 };
            setIsSignedIn(true);
            setNeedsReauth(false);
            settle(null, resp.access_token);
            try {
                const info = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
                    headers: { Authorization: `Bearer ${resp.access_token}` },
                }).then((r) => r.json());
                setEmail(info.email ?? null);
                setUserId(info.sub ?? null);
            } catch {
                /* пошта потрібна лише для відображення */
            }
        },
        onError: (e) => { setNeedsReauth(true); settle(new AuthError(e.error ?? 'auth_error')); },
        onNonOAuthError: (e) => { setNeedsReauth(true); settle(new AuthError(e.type)); },
    });

    const getToken = useCallback((): Promise<string> => {
        const t = token.current;
        if (t && t.expiresAt - REFRESH_MARGIN_MS > Date.now()) return Promise.resolve(t.value);

        return new Promise<string>((resolve, reject) => {
            const first = waiters.current.length === 0;   // паралельні виклики чекають на один запит
            const waiter: Waiter = {
                resolve: (v) => { clearTimeout(timer); resolve(v); },
                reject: (e) => { clearTimeout(timer); reject(e); },
            };
            const timer = setTimeout(() => {
                waiters.current = waiters.current.filter((w) => w !== waiter);
                setNeedsReauth(true);
                reject(new AuthError('token_refresh_timeout'));
            }, SILENT_TIMEOUT_MS);
            waiters.current.push(waiter);
            if (first) login({ prompt: '' });             // без вибору акаунта, якщо згоду вже дано
        });
    }, [login]);

    const signOut = useCallback(() => {
        googleLogout();
        token.current = null;
        setIsSignedIn(false);
        setEmail(null);
        setNeedsReauth(false);
        setUserId(null);
    }, []);

    const value = useMemo<AuthContextValue>(
        () => ({ email, userId, isSignedIn, needsReauth, signIn: () => login(), signOut, getToken }),
        [email, userId, isSignedIn, needsReauth, login, signOut, getToken]
    );

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
    const ctx = useContext(AuthContext);
    if (!ctx) throw new Error('useAuth має викликатися всередині AuthProvider');
    return ctx;
}