import { createContext, ReactNode, useContext, useEffect, useMemo, useRef, useSyncExternalStore } from 'react';
import { useAuth } from '../auth/AuthContext';
import * as drive from '../drive';
import { AppData } from './appData';
import { localStore } from './localDb';
import { EngineState, SyncEngine } from './SyncEngine';

const LAST_USER_KEY = 'tutor:lastUserId';

interface DataStoreValue extends EngineState {
    update: (mutator: (prev: AppData) => AppData) => void;
    saveNow: () => void;
    wipeLocal: () => Promise<void>;
}

const DataStoreContext = createContext<DataStoreValue | null>(null);

export function DataStoreProvider({ children }: { children: ReactNode }) {
    const { userId, isSignedIn, getToken } = useAuth();
    const getTokenRef = useRef(getToken);
    getTokenRef.current = getToken;

    const engine = useMemo(
        () => new SyncEngine({ getToken: () => getTokenRef.current(), drive, local: localStore }),
        []
    );
    const state = useSyncExternalStore(engine.subscribe, engine.getState);

    // Старт: показати локальну копію останнього користувача, ще до входу в Google
    useEffect(() => {
        void engine.init(localStorage.getItem(LAST_USER_KEY));
    }, [engine]);

    // Вхід або вихід
    useEffect(() => {
        if (isSignedIn && userId) {
            localStorage.setItem(LAST_USER_KEY, userId);
            void engine.connect(userId);
        } else if (!isSignedIn) {
            engine.disconnect();
        }
    }, [engine, isSignedIn, userId]);

    // Повернення мережі та згортання вкладки
    useEffect(() => {
        const onOnline = () => engine.flushNow();
        const onVisibility = () => {
            if (document.visibilityState === 'hidden') engine.flushNow();
        };
        window.addEventListener('online', onOnline);
        document.addEventListener('visibilitychange', onVisibility);
        return () => {
            window.removeEventListener('online', onOnline);
            document.removeEventListener('visibilitychange', onVisibility);
        };
    }, [engine]);

    const actions = useMemo(
        () => ({
            update: (m: (prev: AppData) => AppData) => engine.update(m),
            saveNow: () => engine.flushNow(),
            wipeLocal: async () => {
                await engine.wipeLocal();
                localStorage.removeItem(LAST_USER_KEY);
            },
        }),
        [engine]
    );

    return <DataStoreContext.Provider value={{ ...state, ...actions }}>{children}</DataStoreContext.Provider>;
}

export function useDataStore(): DataStoreValue {
    const ctx = useContext(DataStoreContext);
    if (!ctx) throw new Error('useDataStore має викликатися всередині DataStoreProvider');
    return ctx;
}