import { useState } from 'react';
import { useAuth } from './auth/AuthContext';
import { DriveFileMeta, ensureDataFile, readDataFile, writeDataFile } from './drive';

export default function App() {
  const { email, isSignedIn, needsReauth, signIn, signOut, getToken } = useAuth();
  const [meta, setMeta] = useState<DriveFileMeta | null>(null);
  const [data, setData] = useState<Record<string, unknown> | null>(null);
  const [log, setLog] = useState('');

  const run = async (fn: () => Promise<void>) => {
    setLog('');
    try {
      await fn();
    } catch (e) {
      setLog(e instanceof Error ? e.message : String(e));
    }
  };

  const load = () =>
    run(async () => {
      const token = await getToken();
      const m = await ensureDataFile(token, { schemaVersion: 1, touchedAt: null });
      setMeta(m);
      setData((await readDataFile(token, m.id)) as Record<string, unknown>);
    });

  const save = () =>
    run(async () => {
      if (!meta || !data) return;
      const token = await getToken();
      const next = { ...data, touchedAt: new Date().toISOString() };
      setMeta(await writeDataFile(token, meta.id, next));
      setData(next);
    });

  return (
    <div style={{ padding: 24, fontFamily: 'sans-serif' }}>
      {!isSignedIn ? (
        <button onClick={signIn}>Увійти через Google</button>
      ) : (
        <>
          <p>Ви увійшли як {email ?? '…'} <button onClick={signOut}>Вийти</button></p>
          {needsReauth && <button onClick={signIn}>Продовжити сесію</button>}
          <button onClick={load}>Завантажити data.json</button>{' '}
          <button onClick={save} disabled={!meta}>Записати тест</button>
          {meta && <p>Файл {meta.id}, змінено {meta.modifiedTime}, версія {meta.version}</p>}
          <pre>{JSON.stringify(data, null, 2)}</pre>
        </>
      )}
      {log && <p style={{ color: 'crimson' }}>{log}</p>}
    </div>
  );
}