const API = 'https://www.googleapis.com';
export const DATA_FILE_NAME = 'data.json';
const META_FIELDS = 'id,modifiedTime,version';

export interface DriveFileMeta {
    id: string;
    modifiedTime: string;   // ISO, потрібен для перевірки конфліктів (3.4)
    version: string;
}

export class DriveError extends Error {
    constructor(public status: number, message: string) {
        super(message);
    }
}

async function api(token: string, url: string, init: RequestInit = {}): Promise<Response> {
    const res = await fetch(url, {
        ...init,
        headers: { Authorization: `Bearer ${token}`, ...(init.headers ?? {}) },
    });
    if (!res.ok) throw new DriveError(res.status, `Drive ${res.status}: ${await res.text()}`);
    return res;
}

export async function findDataFile(token: string): Promise<DriveFileMeta | null> {
    const q = encodeURIComponent(`name='${DATA_FILE_NAME}' and trashed=false`);
    const res = await api(
        token,
        `${API}/drive/v3/files?spaces=appDataFolder&q=${q}&orderBy=modifiedTime desc&fields=files(${META_FIELDS})`
    );
    const data = await res.json();
    return data.files?.[0] ?? null;   // якщо дублікатів кілька, беремо найновіший
}

export async function createDataFile(token: string, content: object): Promise<DriveFileMeta> {
    const boundary = 'tutor_boundary';
    const metadata = { name: DATA_FILE_NAME, parents: ['appDataFolder'], mimeType: 'application/json' };
    const body =
        `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n` +
        `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(content)}\r\n` +
        `--${boundary}--`;
    const res = await api(token, `${API}/upload/drive/v3/files?uploadType=multipart&fields=${META_FIELDS}`, {
        method: 'POST',
        headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },
        body,
    });
    return res.json();
}

// Знайти файл або створити з початковим вмістом. Паралельні виклики не створюють дублікатів.
let ensuring: Promise<DriveFileMeta> | null = null;
export function ensureDataFile(token: string, initial: object): Promise<DriveFileMeta> {
    if (!ensuring) {
        ensuring = (async () => (await findDataFile(token)) ?? (await createDataFile(token, initial)))().finally(
            () => { ensuring = null; }
        );
    }
    return ensuring;
}

export async function getFileMeta(token: string, id: string): Promise<DriveFileMeta> {
    const res = await api(token, `${API}/drive/v3/files/${id}?fields=${META_FIELDS}`);
    return res.json();
}

export async function readDataFile(token: string, id: string): Promise<unknown> {
    const res = await api(token, `${API}/drive/v3/files/${id}?alt=media`);
    return res.json();
}

export async function writeDataFile(token: string, id: string, content: object): Promise<DriveFileMeta> {
    const res = await api(token, `${API}/upload/drive/v3/files/${id}?uploadType=media&fields=${META_FIELDS}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json; charset=UTF-8' },
        body: JSON.stringify(content),
    });
    return res.json();
}