import { AuthError } from '../auth/errors';
import { DriveError, DriveFileMeta } from '../drive';
import { AppData, createEmptyData, parseAppData } from './appData';
import { EMPTY_SYNC, LocalStore, SyncInfo } from './localDb';

export type SaveStatus =
    | 'loading'     // підключення до Диска
    | 'saved'       // локальна копія збігається з Диском
    | 'pending'     // зміни чекають на відправку
    | 'saving'      // іде запис на Диск
    | 'offline'     // немає мережі: дані лише на цьому пристрої, повтор автоматично
    | 'error'       // помилка Диска, повтор автоматично
    | 'needsLogin'  // потрібен вхід у Google, локальні зміни збережені
    | 'conflict';   // змінено і тут, і на Диску (розв'язується в 3.4)

export interface EngineState {
    data: AppData | null;
    status: SaveStatus;
    lastError: string | null;
}

export interface DriveApi {
    findDataFile(token: string): Promise<DriveFileMeta | null>;
    createDataFile(token: string, content: object): Promise<DriveFileMeta>;
    readDataFile(token: string, id: string): Promise<unknown>;
    writeDataFile(token: string, id: string, content: object): Promise<DriveFileMeta>;
}

export interface EngineDeps {
    getToken: () => Promise<string>;
    drive: DriveApi;
    local: LocalStore;
    debounceMs?: number;
    retryDelaysMs?: number[];
}

const DEFAULT_DEBOUNCE_MS = 2000;
const DEFAULT_RETRY_DELAYS = [5_000, 15_000, 30_000, 60_000];

export class SyncEngine {
    private state: EngineState = { data: null, status: 'loading', lastError: null };
    private listeners = new Set<() => void>();
    private userId: string | null = null;
    private sync: SyncInfo = { ...EMPTY_SYNC };
    private connected = false;
    private saving = false;
    private connecting: Promise<void> | null = null;
    private rev = 0;          // лічильник локальних змін
    private retryIdx = 0;
    private timer: ReturnType<typeof setTimeout> | null = null;

    constructor(private deps: EngineDeps) { }

    // ---- стан для React (useSyncExternalStore) ----
    subscribe = (listener: () => void) => {
        this.listeners.add(listener);
        return () => { this.listeners.delete(listener); };
    };
    getState = () => this.state;

    private setState(patch: Partial<EngineState>) {
        this.state = { ...this.state, ...patch };
        this.listeners.forEach((l) => l());
    }

    // ---- життєвий цикл ----

    /** Старт без мережі: показати локальну копію останнього користувача. */
    async init(lastUserId: string | null): Promise<void> {
        if (this.userId) return;                 // користувач уже відкритий
        if (lastUserId) await this.openCached(lastUserId);
        else this.setState({ status: 'needsLogin' });
    }

    /** Після входу в Google. Паралельні виклики об'єднуються. */
    connect(userId: string): Promise<void> {
        if (!this.connecting) {
            this.connecting = this.doConnect(userId).finally(() => { this.connecting = null; });
        }
        return this.connecting;
    }

    disconnect(): void {
        this.connected = false;
        this.cancelTimer();
        if (this.state.status !== 'conflict') this.setState({ status: 'needsLogin' });
    }

    /** Видалити локальну копію (наприклад, на чужому комп'ютері). */
    async wipeLocal(): Promise<void> {
        const id = this.userId;
        this.disconnect();
        if (id) await this.deps.local.clear(id);
        this.userId = null;
        this.sync = { ...EMPTY_SYNC };
        this.rev = 0;
        this.setState({ data: null, status: 'needsLogin', lastError: null });
    }

    // ---- зміни даних ----

    update(mutator: (prev: AppData) => AppData): void {
        const prev = this.state.data;
        if (!prev || !this.userId) throw new Error('Дані ще не завантажено');
        const next = mutator(prev);
        this.rev++;
        this.sync = { ...this.sync, dirty: true };
        const status: SaveStatus =
            this.state.status === 'conflict' ? 'conflict' : this.connected ? 'pending' : this.state.status;
        this.setState({ data: next, status });
        void this.persist(next);
        if (this.connected && status !== 'conflict') this.schedule(this.deps.debounceMs ?? DEFAULT_DEBOUNCE_MS);
    }

    /** Відправити негайно (кнопка, повернення мережі, згортання вкладки). */
    flushNow(): void {
        if (this.state.status === 'needsLogin') return;   // без входу запитувати токен марно
        this.cancelTimer();
        void this.retry();
    }

    // ---- внутрішня логіка ----

    private async openCached(userId: string) {
        this.userId = userId;
        this.connected = false;
        const cached = await this.deps.local.load(userId);
        this.sync = cached?.sync ?? { ...EMPTY_SYNC };
        this.setState({ data: cached?.data ?? null, status: 'needsLogin', lastError: null });
    }

    private async doConnect(userId: string) {
        if (this.userId !== userId || this.state.data === null) {
            this.connected = false;
            await this.openCached(userId);
        }
        this.setState({ status: 'loading', lastError: null });
        try {
            const token = await this.deps.getToken();
            const found = await this.deps.drive.findDataFile(token);

            if (!found) {
                // На Диску файла немає: створюємо його з локальних (або порожніх) даних
                const initial = this.state.data ?? createEmptyData();
                const meta = await this.deps.drive.createDataFile(token, initial);
                this.sync = { fileId: meta.id, modifiedTime: meta.modifiedTime, version: meta.version, dirty: false };
                this.connected = true;
                await this.persist(initial);
                this.setState({ data: initial, status: 'saved' });
                return;
            }

            const remoteChanged = found.id !== this.sync.fileId || found.modifiedTime !== this.sync.modifiedTime;

            if (!remoteChanged) {
                // Диск такий самий, як при останній синхронізації
                this.connected = true;
                if (this.sync.dirty) await this.flush();
                else this.setState({ status: 'saved' });
            } else if (!this.sync.dirty || this.state.data === null) {
                // На Диску новіше, локальних змін немає: беремо з Диска
                const remote = parseAppData(await this.deps.drive.readDataFile(token, found.id));
                this.sync = { fileId: found.id, modifiedTime: found.modifiedTime, version: found.version, dirty: false };
                this.connected = true;
                await this.persist(remote);
                this.setState({ data: remote, status: 'saved' });
            } else {
                // Змінено і тут, і на Диску: нічого не перезаписуємо, розв'язання в 3.4
                this.connected = true;
                this.setState({ status: 'conflict' });
            }
        } catch (e) {
            this.handleError(e);
        }
    }

    private async flush(): Promise<void> {
        const data = this.state.data;
        const fileId = this.sync.fileId;
        if (this.saving || !this.connected || !data || !fileId || !this.sync.dirty) return;
        if (this.state.status === 'conflict') return;

        this.saving = true;
        const rev = this.rev;
        this.setState({ status: 'saving', lastError: null });
        try {
            const token = await this.deps.getToken();
            const meta = await this.deps.drive.writeDataFile(token, fileId, data);
            this.retryIdx = 0;
            const unchanged = rev === this.rev;   // чи не змінювали дані, поки йшов запис
            this.sync = { fileId: meta.id, modifiedTime: meta.modifiedTime, version: meta.version, dirty: !unchanged };
            await this.persist(this.state.data ?? data);
            if (unchanged) {
                this.setState({ status: 'saved' });
            } else {
                this.setState({ status: 'pending' });
                this.schedule(this.deps.debounceMs ?? DEFAULT_DEBOUNCE_MS);
            }
        } catch (e) {
            this.handleError(e);
        } finally {
            this.saving = false;
        }
    }

    private retry(): Promise<void> {
        if (this.connected) return this.flush();
        if (this.userId) return this.connect(this.userId);
        return Promise.resolve();
    }

    private handleError(e: unknown) {
        const message = e instanceof Error ? e.message : String(e);

        if (e instanceof AuthError || (e instanceof DriveError && e.status === 401)) {
            this.connected = false;
            this.setState({ status: 'needsLogin', lastError: message });
            return;
        }
        if (e instanceof DriveError && e.status === 404) {
            // Файл на Диску зник: підключаємося наново, файл буде створено з локальних даних
            this.connected = false;
            this.sync = { ...this.sync, fileId: null, modifiedTime: null, version: null };
            this.schedule(0);
            return;
        }
        const offline = (typeof navigator !== 'undefined' && !navigator.onLine) || e instanceof TypeError;
        this.setState({ status: offline ? 'offline' : 'error', lastError: message });
        const delays = this.deps.retryDelaysMs ?? DEFAULT_RETRY_DELAYS;
        this.schedule(delays[Math.min(this.retryIdx++, delays.length - 1)]);
    }

    private async persist(data: AppData) {
        if (!this.userId) return;
        try {
            await this.deps.local.save(this.userId, data, { ...this.sync });
        } catch (e) {
            this.setState({
                lastError: 'Не вдалося зберегти локальну копію: ' + (e instanceof Error ? e.message : String(e)),
            });
        }
    }

    private schedule(ms: number) {
        this.cancelTimer();
        this.timer = setTimeout(() => {
            this.timer = null;
            void this.retry();
        }, ms);
    }

    private cancelTimer() {
        if (this.timer) {
            clearTimeout(this.timer);
            this.timer = null;
        }
    }
}